/**
 * News nav icon — the dot-matrix Earth.
 *
 *   decodeLand(bits, …)   base64 land mask (utils/navGlobeLand.ts, generated by
 *                         scripts/nav-globe-land.ts) → flat [lon, lat, lon, lat, …]
 *   landPoints()          the decoded mask, memoised for the whole app
 *   globeDots(points, …)  orthographic projection → three SVG paths of `h0`
 *                         dots (front / mid / rim) so the icon can fade dots
 *                         toward the limb with three <path> elements in total
 *   parallelPath(lat, …)  the visible arc of a parallel (static graticule)
 *
 * Pure: no DOM, no Date, works in the browser, in SSR and in vitest.
 */
import { orthographic } from '~/utils/navIcons'
import { LAND_BITS, LAND_COLS, LAND_ROWS, LAND_STEP_DEG } from '~/utils/navGlobeLand'

/**
 * Decode a row-major, MSB-first bit mask into land-cell centres.
 * Row 0 is the northernmost band (lat 90 - step/2), column 0 the westernmost
 * (lon -180 + step/2). Returns pairs lon, lat in degrees.
 */
export function decodeLand(bits: string, cols: number, rows: number, step: number): Float32Array {
  const bin = atob(bits)
  const out: number[] = []
  const n = Math.min(cols * rows, bin.length * 8)
  for (let i = 0; i < n; i++) {
    if (!(bin.charCodeAt(i >> 3) & (0x80 >> (i & 7)))) continue
    const row = Math.floor(i / cols)
    const col = i - row * cols
    out.push(-180 + step / 2 + col * step, 90 - step / 2 - row * step)
  }
  return Float32Array.from(out)
}

let land: Float32Array | null = null

/** Every land cell of the generated mask (decoded once per process). */
export function landPoints(): Float32Array {
  return (land ??= decodeLand(LAND_BITS, LAND_COLS, LAND_ROWS, LAND_STEP_DEG))
}

export interface GlobeDots {
  /** depth > 0.6 — facing the viewer, drawn brightest and largest */
  front: string
  /** 0.25 < depth ≤ 0.6 */
  mid: string
  /** 0 < depth ≤ 0.25 — next to the limb, drawn dimmest and smallest */
  rim: string
}

const f2 = (n: number) => String(Math.round(n * 100) / 100)

/**
 * Project land cells onto a globe of `radius` centred at (cx, cy), looking at
 * (lon0, lat0). Each visible cell becomes `M x y h0` — a zero-length segment a
 * round line cap turns into a dot — so one <path> renders a whole depth band.
 * Cells on the far hemisphere are dropped. Screen y grows downward.
 */
export function globeDots(points: Float32Array, lon0: number, lat0: number, radius: number, cx: number, cy: number): GlobeDots {
  const front: string[] = []
  const mid: string[] = []
  const rim: string[] = []
  for (let i = 0; i + 1 < points.length; i += 2) {
    const p = orthographic(points[i]!, points[i + 1]!, lon0, lat0)
    if (p.depth <= 0) continue
    const seg = `M${f2(cx + p.x * radius)} ${f2(cy - p.y * radius)}h0`
    ;(p.depth > 0.6 ? front : p.depth > 0.25 ? mid : rim).push(seg)
  }
  return { front: front.join(''), mid: mid.join(''), rim: rim.join('') }
}

/**
 * Visible (near-side) arc of the parallel at `lat` on a globe tilted by
 * `lat0`, as a polyline path. Parallels are symmetric about the polar axis,
 * so this does not depend on the view longitude: compute it once.
 */
export function parallelPath(lat: number, lat0: number, radius: number, cx: number, cy: number, samples = 24): string {
  const r = Math.PI / 180
  // depth = 0 where cos λ = −tan φ0 · tan φ: the limb crossings of this parallel
  const c = -Math.tan(lat0 * r) * Math.tan(lat * r)
  if (c >= 1) return '' // whole parallel on the far side
  const lmax = c <= -1 ? 180 : Math.acos(c) / r
  const pts: string[] = []
  for (let k = 0; k <= samples; k++) {
    const p = orthographic(-lmax + (2 * lmax * k) / samples, lat, 0, lat0)
    pts.push(`${k ? 'L' : 'M'}${f2(cx + p.x * radius)} ${f2(cy - p.y * radius)}`)
  }
  return pts.join('')
}
